const mode = $json.query?.mode ?? "ten";
const out = {};
if (mode === "ten") {
  const t0 = Date.now();
  for (let i = 0; i < 10; i++) {
    await helpers.httpRequest({ url: 'http://127.0.0.1:5680/echo?i=' + i, json: true });
  }
  out.ms = Date.now() - t0;
} else if (mode === "ssrf") {
  try { await helpers.httpRequest({ url: "http://169.254.169.254/latest/meta-data/" }); out.blocked = false; }
  catch (e) { out.blocked = true; out.message = e.message; }
} else if (mode === "proxy") {
  const r = await helpers.httpRequest({ url: 'http://127.0.0.1:5680/echo?via=proxy', json: true });
  out.viaProxy = r.viaProxy === true;
}
return [{ json: out }];
